/**
 * Table. A recessed screen well holding rows; the
 * header is a machine label, the body is readout text. Composes var(--echo-*).
 */
.echo-table__scroll {
  /*
   * The containing block for what's hidden inside it (the live region after
   * the table): without it, a visually hidden element sat at the bottom of a
   * tall scrolled table, outside the clip, and stretched the page by the
   * table's whole height.
   */
  position: relative;
  overflow-x: auto;
  border-radius: var(--echo-radius-lg);
  background: linear-gradient(160deg, var(--echo-well) 0%, var(--echo-lcd) 100%);
  box-shadow:
    inset 0 2px 6px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.65 * var(--echo-shade, 1) * 100%), transparent),
    inset 0 -1px 0 rgb(255 255 255 / calc(0.04 * var(--echo-gloss, 1)));
}

.echo-table__scroll:focus-visible {
  /* Drawn only in forced colors, which drops the shadow ring. */
  outline: 2px solid transparent;
  outline-offset: 2px;
  box-shadow:
    inset 0 2px 6px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.65 * var(--echo-shade, 1) * 100%), transparent),
    0 0 0 2px var(--echo-surface),
    0 0 0 4px var(--echo-accent-ink, var(--echo-accent-glow));
}

.echo-table {
  width: 100%;
  border-collapse: collapse;
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-sm);
}

.echo-table__caption {
  padding: var(--echo-space-6) var(--echo-space-7) 0;
  text-align: start;
  font-size: var(--echo-text-3xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-label, 0.2em);
  text-transform: uppercase;
  color: var(--echo-text-dim);
}

/*
 * Row rules are the Divider's seam (2026-09-18): a dark groove over a light
 * lip, fading out at both ends of the row. They used to be flat hairlines —
 * the one ruled surface in the library that did not look like the Divider,
 * and the Console template put the two side by side.
 *
 * Drawn as background layers on the cells rather than as borders, because a
 * border cannot fade. The first and last cell carry the fade-in and fade-out;
 * every cell between is solid, so the row reads as ONE groove.
 *
 * On the dark well the groove is nearly the well's own colour, so the LIP is
 * what separates rows — by luminance, which survives every colour-vision
 * deficiency and greyscale alike. The header's lip is brighter: it closes the
 * head off from the body.
 */
.echo-table {
  --echo-table-groove: var(--echo-seam);
  --echo-table-lip: color-mix(in srgb, var(--echo-text) 7%, transparent);
  --echo-table-fade: var(--echo-space-12);
}

.echo-table__head {
  --echo-table-lip: color-mix(in srgb, var(--echo-text) 13%, transparent);
}

.echo-table__header-cell,
.echo-table__cell {
  --echo-table-in: 0%;
  --echo-table-out: 100%;
  background-image:
    linear-gradient(
      90deg,
      transparent 0,
      var(--echo-table-groove) var(--echo-table-in),
      var(--echo-table-groove) var(--echo-table-out),
      transparent 100%
    ),
    linear-gradient(
      90deg,
      transparent 0,
      var(--echo-table-lip) var(--echo-table-in),
      var(--echo-table-lip) var(--echo-table-out),
      transparent 100%
    );
  background-size:
    100% 1px,
    100% 1px;
  background-position:
    left bottom 1px,
    left bottom;
  background-repeat: no-repeat;
}

.echo-table__row > :first-child {
  --echo-table-in: var(--echo-table-fade);
}

.echo-table__row > :last-child {
  --echo-table-out: calc(100% - var(--echo-table-fade));
}

.echo-table__header-cell {
  padding: var(--echo-space-5) var(--echo-space-7);
  white-space: nowrap;
  font-size: var(--echo-text-3xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-wider, 0.12em);
  text-transform: uppercase;
  color: var(--echo-text-dim);
}

.echo-table__cell {
  padding: var(--echo-space-5) var(--echo-space-7);
  color: var(--echo-text);
}

/* The row under the pointer lifts — a luminance step, not a colour. */
@media (hover: hover) {
  .echo-table__body .echo-table__row:hover .echo-table__cell,
  .echo-table__body .echo-table__row:hover .echo-table__header-cell {
    background-color: color-mix(in oklab, var(--echo-text) 5%, transparent);
  }
}

.echo-table[data-striped] .echo-table__body .echo-table__row:nth-child(even) .echo-table__cell,
.echo-table[data-striped] .echo-table__body .echo-table__row:nth-child(even) .echo-table__header-cell {
  background-color: color-mix(in oklab, var(--echo-text) 3.5%, transparent);
}

/* The last row sits on the well's edge; a groove there is a double line. */
.echo-table__body .echo-table__row:last-child .echo-table__cell,
.echo-table__body .echo-table__row:last-child .echo-table__header-cell {
  background-image: none;
}

.echo-table__header-cell[data-align="start"],
.echo-table__cell[data-align="start"] {
  text-align: start;
}

.echo-table__header-cell[data-align="end"],
.echo-table__cell[data-align="end"] {
  text-align: end;
}

/* Numbers line up or they are not worth tabulating. */
.echo-table__cell[data-numeric] {
  font-family: var(--echo-font-lcd, ui-monospace, SFMono-Regular, Menlo, monospace);
  font-variant-numeric: tabular-nums;
}

/* A row header is a label, not data. */
.echo-table__header-cell[scope="row"] {
  font-size: var(--echo-text-sm);
  letter-spacing: var(--echo-tracking-normal, 0);
  text-transform: none;
  color: var(--echo-text);
}

.echo-table__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* ------------------------------------------------------------------ size */

/* Row height from the control scale, so a table sits on the same rhythm as the controls beside it. */
.echo-table[data-size="sm"] {
  --echo-table-row: var(--echo-control-compact, 32px);
}
.echo-table[data-size="md"] {
  --echo-table-row: var(--echo-control-default, 44px);
}
.echo-table[data-size="lg"] {
  --echo-table-row: var(--echo-control-large, 60px);
}
.echo-table[data-size] .echo-table__row {
  height: var(--echo-table-row);
}
.echo-table[data-size] .echo-table__cell,
.echo-table[data-size] .echo-table__header-cell {
  padding-block: 0;
  vertical-align: middle;
}
.echo-table[data-size="sm"] .echo-table__cell,
.echo-table[data-size="sm"] .echo-table__header-cell {
  padding-inline: var(--echo-space-5);
}

/* ------------------------------------------------ height, header, window */

/* A table with its own height scrolls inside the well, and its header stays at the top. */
.echo-table__scroll[data-height] {
  overflow: auto;
  overscroll-behavior: contain;
}
.echo-table[data-sticky] .echo-table__head .echo-table__header-cell {
  position: sticky;
  top: 0;
  z-index: var(--echo-z-raised, 1);
  /* Opaque, so the rows pass under it. */
  background-color: var(--echo-well);
}
/* Every drawn row is exactly one control height: one line each, the window is arithmetic. */
.echo-table[data-virtual] .echo-table__cell,
.echo-table[data-virtual] .echo-table__header-cell {
  white-space: nowrap;
}
.echo-table__spacer > td {
  padding: 0;
  background-image: none;
}

/* ------------------------------------------------------------------ sort */

.echo-table__sort {
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: var(--echo-space-3);
  min-height: 24px;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--echo-radius-sm);
  background: none;
  color: inherit;
  font: inherit;
  /* A button resets letter-spacing; the header's own tracking. */
  letter-spacing: var(--echo-tracking-wider, 0.12em);
  text-transform: inherit;
  cursor: pointer;
}
.echo-table__sort[data-active] {
  color: var(--echo-text);
}
.echo-table__sort:focus-visible {
  outline: 2px solid transparent;
  outline-offset: 2px;
  box-shadow: var(--echo-shadow-ring, 0 0 0 2px var(--echo-surface), 0 0 0 4px var(--echo-accent-ink, var(--echo-accent-glow)));
}
@media (hover: hover) {
  .echo-table__sort:hover {
    color: var(--echo-text);
  }
}

/* The LED pips: up lights for ascending, down for descending. Shape and place say the direction. */
.echo-table__pips {
  display: inline-grid;
  gap: var(--echo-space-1);
}
.echo-table__pips > i {
  display: block;
  width: 7px;
  height: 4px;
  background: color-mix(in oklab, var(--echo-text) 22%, transparent);
  transition: background var(--echo-duration-swap) var(--echo-ease-swap);
}
.echo-table__pips > i:first-child {
  clip-path: polygon(50% 0, 100% 100%, 0 100%);
}
.echo-table__pips > i:last-child {
  clip-path: polygon(0 0, 100% 0, 50% 100%);
}
.echo-table__pips > i[data-lit] {
  background: var(--echo-accent-glow);
}

/* ---------------------------------------------- selection, actions, press */

.echo-table__select {
  width: 1%;
  padding-inline-end: 0;
}
.echo-table__actions {
  width: 1%;
  white-space: nowrap;
  text-align: end;
}
/* A selected row lifts a step in luminance; its Checkbox says so in words. */
.echo-table__row[data-selected] > .echo-table__cell,
.echo-table__row[data-selected] > .echo-table__header-cell {
  background-color: color-mix(in oklab, var(--echo-text) 7%, transparent);
}
.echo-table__row[data-pressable] {
  cursor: pointer;
}
.echo-table__press {
  appearance: none;
  display: block;
  width: 100%;
  min-height: 24px;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: var(--echo-radius-sm);
  background: none;
  color: inherit;
  font: inherit;
  /* A button resets letter-spacing; a row's label reads at the body's. */
  letter-spacing: var(--echo-tracking-normal, 0);
  text-align: inherit;
  text-transform: inherit;
  cursor: pointer;
}
.echo-table__press:focus-visible {
  outline: 2px solid transparent;
  outline-offset: 2px;
  box-shadow: var(--echo-shadow-ring, 0 0 0 2px var(--echo-surface), 0 0 0 4px var(--echo-accent-ink, var(--echo-accent-glow)));
}
/* A pressed row gives under the hand. */
.echo-table__row[data-pressable]:active > .echo-table__cell,
.echo-table__row[data-pressable]:active > .echo-table__header-cell {
  background-color: color-mix(in oklab, var(--echo-well) 55%, transparent);
}
@media (prefers-reduced-motion: no-preference) {
  .echo-table__row[data-pressable]:active {
    transform: translateY(1px);
  }
}

/* ------------------------------------------------------- empty, loading */

.echo-table__empty {
  padding-block: var(--echo-space-10);
  text-align: center;
  color: var(--echo-text-dim);
}
.echo-table__skeleton {
  display: block;
  width: var(--echo-table-skeleton, 60%);
  height: 0.7em;
  border-radius: var(--echo-radius-full);
  background: color-mix(in oklab, var(--echo-text) 10%, transparent);
}
@media (prefers-reduced-motion: no-preference) {
  .echo-table__skeleton {
    animation: echo-table-waiting 1.6s ease-in-out infinite;
  }
}
@keyframes echo-table-waiting {
  50% {
    opacity: 0.45;
  }
}

@media (forced-colors: active) {
  .echo-table__pips > i {
    forced-color-adjust: none;
    background: GrayText;
  }
  .echo-table__pips > i[data-lit] {
    background: CanvasText;
  }
  .echo-table__sort:focus-visible,
  .echo-table__press:focus-visible {
    outline-color: Highlight;
  }
  .echo-table__skeleton {
    forced-color-adjust: none;
    background: GrayText;
  }
}

/**
 * Table. Rows of data in a recessed screen well.
 *
 * Two ways in, one component:
 *
 * - **Compound**, for content you lay out yourself:
 *     <Table caption="…">
 *       <Table.Head><Table.Row><Table.HeaderCell>…</Table.HeaderCell></Table.Row></Table.Head>
 *       <Table.Body><Table.Row><Table.Cell>…</Table.Cell></Table.Row></Table.Body>
 *     </Table>
 * - **Data**, for rows Table can sort, select, filter and window for you:
 *     <Table caption="…" columns={columns} rows={rows} getRowId={(r) => r.id} />
 *   (table-data.tsx, a client component; this file stays usable from a
 *   server component when it's given children).
 *
 * Two a11y decisions worth keeping:
 *
 * 1. The caption is required and rendered as a real <caption>. A table
 *    without one is an unlabelled grid of numbers to anyone not looking at it.
 * 2. A wide table scrolls inside a container that is a labelled, FOCUSABLE
 *    region. An overflow container that cannot take focus is unreachable by
 *    keyboard — axe flags exactly this, and it is easy to ship without
 *    noticing because a mouse hides the problem.
 *
 * Consumes only var(--echo-*) via table.css.
 */
import type { HTMLAttributes, ReactElement, ReactNode, TdHTMLAttributes, ThHTMLAttributes } from "react";
import { TableData, type TableDataProps } from "./table-data";
import "./table.css";

const cx = (...c: (string | undefined)[]) => c.filter(Boolean).join(" ");

export type CellAlign = "start" | "end";

/** Row height, from the control scale: `sm` 32px for dense screens, `md` 44px, `lg` 60px (at default density). */
export type TableSize = "sm" | "md" | "lg";

export interface TableProps extends HTMLAttributes<HTMLTableElement> {
  /** What this table is. Required — it names the table and its scroll region. */
  caption: string;
  /** Hide the caption visually. It still names the table and its region. */
  hideCaption?: boolean;
  /**
   * Alternate rows carry a faint band. Off by default — the rules already
   * separate rows; stripes earn their place on wide tables, where the eye has
   * to carry a row across a long gap.
   */
  striped?: boolean;
  /** Each row's height, from the control scale. Left out, rows are as tall as their content. */
  size?: TableSize;
  children?: ReactNode;
}

/*
 * `Row` defaults to `any` for rows TypeScript can't read (JSON, say): with
 * nothing to infer from, it would be `unknown`, and `getRowId={(row) => row.id}`
 * wouldn't compile. Typed rows are inferred as usual.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
function TableRoot<Row = any>(props: TableProps | TableDataProps<Row>): ReactElement {
  if ("columns" in props) return <TableData {...props} />;
  const { caption, hideCaption, striped, size, className, children, ...rest } = props;
  return (
    <div
      className="echo-table__scroll"
      role="region"
      aria-label={caption}
      // Keyboard users must be able to reach and scroll a wide table.
      tabIndex={0}
    >
      <table className={cx("echo-table", className)} data-striped={striped ? "" : undefined} data-size={size} {...rest}>
        <caption className={cx("echo-table__caption", hideCaption ? "echo-table__sr" : undefined)}>
          {caption}
        </caption>
        {children}
      </table>
    </div>
  );
}

function TableHead({ className, ...rest }: HTMLAttributes<HTMLTableSectionElement>) {
  return <thead className={cx("echo-table__head", className)} {...rest} />;
}

function TableBody({ className, ...rest }: HTMLAttributes<HTMLTableSectionElement>) {
  return <tbody className={cx("echo-table__body", className)} {...rest} />;
}

function TableRow({ className, ...rest }: HTMLAttributes<HTMLTableRowElement>) {
  return <tr className={cx("echo-table__row", className)} {...rest} />;
}

/**
 * `align` shadows the deprecated HTML presentation attribute, which only
 * accepts left/right/center. Omitting it lets the prop take the logical
 * start/end values instead — and the legacy attribute is not worth keeping.
 */
export interface HeaderCellProps extends Omit<ThHTMLAttributes<HTMLTableCellElement>, "align"> {
  align?: CellAlign;
  /** "col" (default) for a column heading, "row" for a leading row label. */
  scope?: "col" | "row";
}

function TableHeaderCell({ className, align = "start", scope = "col", ...rest }: HeaderCellProps) {
  return (
    <th
      className={cx("echo-table__header-cell", className)}
      data-align={align}
      scope={scope}
      {...rest}
    />
  );
}

export interface CellProps extends Omit<TdHTMLAttributes<HTMLTableCellElement>, "align"> {
  align?: CellAlign;
  /** Tabular figures and end alignment for numbers. */
  numeric?: boolean;
}

function TableCell({ className, align, numeric, ...rest }: CellProps) {
  return (
    <td
      className={cx("echo-table__cell", className)}
      data-align={align ?? (numeric ? "end" : "start")}
      data-numeric={numeric ? "" : undefined}
      {...rest}
    />
  );
}

export const Table = Object.assign(TableRoot, {
  Head: TableHead,
  Body: TableBody,
  Row: TableRow,
  HeaderCell: TableHeaderCell,
  Cell: TableCell,
});

"use client";

/**
 * Table's data mode: give it `columns` and `rows`, and it sorts, selects,
 * filters and windows them, in the same recessed well as a table laid out by
 * hand.
 *
 * - **Sort:** a sortable column's header is a button; its LED pips light the
 *   direction, and the header carries `aria-sort`. Controlled (`sort` and
 *   `onSortChange`) or not (`defaultSort`).
 * - **Select:** `selectable` puts a Checkbox on every row and one in the
 *   header that selects every row shown, and reads "some" when some are.
 *   Controlled (`selected`) or not (`defaultSelected`), by row id.
 * - **Filter:** `filter` is the query (the builder's own search Field sets
 *   it); a row stays when any of its column values contains it.
 * - **Size:** row heights from the control scale (`sm`, `md`, `lg`).
 * - **Height:** a table with its own `height` scrolls inside the well, and
 *   its header stays at the top.
 * - **Virtual rows:** with `virtual`, only the rows in view are drawn. Every
 *   row is exactly one control height, so nothing is measured: the window is
 *   arithmetic, and there's no dependency.
 * - **Empty and loading:** a row that says so, and a table that's busy.
 * - **Row actions** end each row; **`onRowPress`** makes the row a press,
 *   through a real button in its label cell.
 * - **Motion:** rows that move slide to their new place and new rows fade in
 *   (FLIP); a pressed row gives under the hand. Neither under reduced motion.
 *
 * What changes is said in a polite live region: the sort, how many rows a
 * filter leaves, and loading.
 */
import { useEffect, useLayoutEffect, useMemo, useRef, useState, type CSSProperties, type HTMLAttributes, type MouseEvent, type ReactNode } from "react";
import gsap from "gsap";
import { useSoundOptional } from "echo-ui-core/sound";
import { timing, useReducedMotionRef } from "echo-ui-core/tactile";
import { Checkbox } from "../checkbox";
import type { CellAlign, TableSize } from "./table";

const cx = (...c: (string | false | undefined)[]) => c.filter(Boolean).join(" ");

export type SortDirection = "ascending" | "descending";

export interface TableSort {
  /** The `key` of the column. */
  column: string;
  direction: SortDirection;
}

/** What a column holds for a row: what's sorted, filtered and, without a `cell`, shown. */
export type CellValue = string | number | Date | null | undefined;

export interface TableColumn<Row> {
  /** The column's id, and the row field it reads when there's no `value`. */
  key: string;
  /** The column's name: its heading, its sort button's name, and what the sort is announced by. */
  header: string;
  /** The value for a row. Default: `row[key]`. */
  value?: (row: Row) => CellValue;
  /** How the cell shows. Default: the value as text. */
  cell?: (row: Row) => ReactNode;
  sortable?: boolean;
  align?: CellAlign;
  /** Tabular figures and end alignment. */
  numeric?: boolean;
  /** This column names the row: its cells are row headers, and a row's checkbox is named by it. */
  rowHeader?: boolean;
  /** Include it when filtering. Default true. */
  filterable?: boolean;
}

export interface TableDataProps<Row> extends Omit<HTMLAttributes<HTMLTableElement>, "children"> {
  /** What this table is. Required — it names the table and its scroll region. */
  caption: string;
  /** Hide the caption visually. It still names the table and its region. */
  hideCaption?: boolean;
  /** Faint bands on alternate rows. */
  striped?: boolean;
  /** Row height from the control scale. Default `md`. */
  size?: TableSize;
  columns: readonly TableColumn<Row>[];
  rows: readonly Row[];
  /** A stable id for a row: what selection is kept by. */
  getRowId: (row: Row) => string;
  /** The sort, controlled. `null` is unsorted. */
  sort?: TableSort | null;
  defaultSort?: TableSort | null;
  onSortChange?: (sort: TableSort) => void;
  /** A Checkbox on every row, and a select-all in the header. */
  selectable?: boolean;
  /** Selected row ids, controlled. */
  selected?: readonly string[];
  defaultSelected?: readonly string[];
  onSelectedChange?: (selected: string[]) => void;
  /** A query: rows whose values contain it stay. */
  filter?: string;
  /** Your own filter, instead of "any value contains the query". */
  filterRows?: (row: Row, query: string) => boolean;
  /** The table's own height (a number is pixels): it scrolls inside, with its header at the top. */
  height?: number | string;
  /** Draw only the rows in view. Needs `height`. */
  virtual?: boolean;
  /** Rows are on their way: placeholder rows, and a busy table. */
  loading?: boolean;
  /** What an empty table says. */
  empty?: ReactNode;
  /** The end of each row: its actions (a Menu, ghost HardwareButtons). */
  rowActions?: (row: Row) => ReactNode;
  /** Make each row a press: its label cell becomes a button, and a click anywhere on the row presses it. */
  onRowPress?: (row: Row) => void;
}

const STEP: Record<TableSize, string> = { sm: "compact", md: "default", lg: "large" };
const DEFAULT_HEIGHT: Record<TableSize, number> = { sm: 32, md: 44, lg: 60 };
/** Rows drawn beyond the view on each side, so a quick scroll doesn't show the gap. */
const OVERSCAN = 6;
/** Above this many rows, moves are not animated: the FLIP costs more than it shows. */
const MOST_ANIMATED = 200;
const LOADING_ROWS = 5;

const collator = new Intl.Collator(undefined, { numeric: true, sensitivity: "base" });

function compare(a: CellValue, b: CellValue): number {
  if (a instanceof Date && b instanceof Date) return a.getTime() - b.getTime();
  if (typeof a === "number" && typeof b === "number") return a - b;
  return collator.compare(String(a), String(b));
}

const text = (value: CellValue) => (value == null ? "" : value instanceof Date ? value.toLocaleDateString() : String(value));

/** Nothing in a row's own controls presses the row: they have jobs of their own. */
const INTERACTIVE = "button, a, input, select, textarea, [role='checkbox'], [role='button'], [role='menuitem']";

export function TableData<Row>({
  caption,
  hideCaption,
  striped,
  size = "md",
  columns,
  rows,
  getRowId,
  sort: sortProp,
  defaultSort = null,
  onSortChange,
  selectable,
  selected: selectedProp,
  defaultSelected = [],
  onSelectedChange,
  filter = "",
  filterRows,
  height,
  virtual,
  loading,
  empty,
  rowActions,
  onRowPress,
  className,
  ...rest
}: TableDataProps<Row>) {
  const sound = useSoundOptional();
  const reduced = useReducedMotionRef();
  const [innerSort, setInnerSort] = useState<TableSort | null>(defaultSort);
  const sort = sortProp === undefined ? innerSort : sortProp;
  const [innerSelected, setInnerSelected] = useState<readonly string[]>(defaultSelected);
  const selectedIds = selectedProp ?? innerSelected;
  const selectedSet = useMemo(() => new Set(selectedIds), [selectedIds]);
  const [said, setSaid] = useState("");

  const valueOf = (column: TableColumn<Row>, row: Row): CellValue =>
    column.value ? column.value(row) : ((row as Record<string, unknown>)[column.key] as CellValue);
  const labelColumn = columns.find((c) => c.rowHeader) ?? columns[0];
  const labelOf = (row: Row) => (labelColumn ? text(valueOf(labelColumn, row)) : getRowId(row)) || getRowId(row);

  // The rows as shown: filtered, then sorted (a stable sort, empty values last either way).
  const query = filter.trim().toLowerCase();
  const shown = useMemo(() => {
    const kept = query
      ? rows.filter((row) =>
          filterRows
            ? filterRows(row, filter)
            : columns.some((c) => c.filterable !== false && text(valueOf(c, row)).toLowerCase().includes(query)),
        )
      : [...rows];
    const by = sort && columns.find((c) => c.key === sort.column);
    if (!by) return kept;
    const sign = sort.direction === "ascending" ? 1 : -1;
    return kept
      .map((row, index) => ({ row, index, value: valueOf(by, row) }))
      .sort((a, b) => {
        if (a.value == null || b.value == null) return a.value == null ? (b.value == null ? a.index - b.index : 1) : -1;
        return sign * compare(a.value, b.value) || a.index - b.index;
      })
      .map((entry) => entry.row);
    // valueOf reads only `columns`, already a dependency.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [rows, columns, sort, query, filter, filterRows]);

  // Said when it changes, not on arrival: loading starting and ending, and what a filter leaves.
  const before = useRef({ loading, query });
  useEffect(() => {
    const was = before.current;
    before.current = { loading, query };
    if (loading && !was.loading) setSaid("Loading rows.");
    else if (!loading && was.loading) setSaid(`${shown.length} rows.`);
    else if (!loading && query !== was.query) setSaid(query ? `${shown.length} of ${rows.length} rows.` : `${rows.length} rows.`);
  }, [loading, query, shown.length, rows.length]);

  /* ----------------------------------------------------------------- sort */

  const setSort = (column: TableColumn<Row>) => {
    const next: TableSort =
      sort?.column === column.key
        ? { column: column.key, direction: sort.direction === "ascending" ? "descending" : "ascending" }
        : { column: column.key, direction: "ascending" };
    if (sortProp === undefined) setInnerSort(next);
    onSortChange?.(next);
    sound?.play("select");
    setSaid(`Sorted by ${column.header}, ${next.direction}.`);
  };

  /* ------------------------------------------------------------ selection */

  const setSelected = (next: string[]) => {
    if (selectedProp === undefined) setInnerSelected(next);
    onSelectedChange?.(next);
  };
  const shownIds = shown.map(getRowId);
  const allShown = shownIds.length > 0 && shownIds.every((id) => selectedSet.has(id));
  const someShown = !allShown && shownIds.some((id) => selectedSet.has(id));
  const selectAll = (on: boolean) => {
    const others = selectedIds.filter((id) => !shownIds.includes(id));
    setSelected(on ? [...others, ...shownIds] : others);
  };
  const selectRow = (id: string, on: boolean) =>
    setSelected(on ? [...selectedIds.filter((s) => s !== id), id] : selectedIds.filter((s) => s !== id));

  /* ------------------------------------------------ the window (virtual) */

  const scroll = useRef<HTMLDivElement>(null);
  const [rowHeight, setRowHeight] = useState(DEFAULT_HEIGHT[size]);
  const [view, setView] = useState({ top: 0, height: 0 });
  useLayoutEffect(() => {
    const el = scroll.current;
    if (!el) return;
    // The row height is the size's control token: read, not measured.
    const px = parseFloat(getComputedStyle(el).getPropertyValue(`--echo-control-${STEP[size]}`));
    if (px) setRowHeight(px);
    if (!virtual) return;
    let frame = 0;
    const read = () => {
      frame = 0;
      setView({ top: el.scrollTop, height: el.clientHeight });
    };
    const soon = () => {
      if (!frame) frame = requestAnimationFrame(read);
    };
    read();
    el.addEventListener("scroll", soon, { passive: true });
    const resized = new ResizeObserver(soon);
    resized.observe(el);
    return () => {
      el.removeEventListener("scroll", soon);
      resized.disconnect();
      if (frame) cancelAnimationFrame(frame);
    };
  }, [size, virtual]);
  const windowed = !!virtual && !loading;
  const start = windowed ? Math.max(0, Math.floor(view.top / rowHeight) - OVERSCAN) : 0;
  const end = windowed ? Math.min(shown.length, start + Math.ceil((view.height || 600) / rowHeight) + 2 * OVERSCAN) : shown.length;
  const drawn = shown.slice(start, end);

  /* --------------------------------------------------------------- motion */

  const rowEls = useRef(new Map<string, HTMLTableRowElement>());
  const tops = useRef(new Map<string, number>());
  const order = drawn.map(getRowId).join("\u0000");
  const lastOrder = useRef(order);
  useLayoutEffect(() => {
    // Windowed rows come and go with the scroll: there's nothing to slide, and nothing worth measuring.
    if (windowed) return;
    const table = scroll.current?.querySelector("table");
    const origin = table?.getBoundingClientRect().top ?? 0;
    const now = new Map([...rowEls.current].map(([id, el]) => [id, el.getBoundingClientRect().top - origin]));
    const was = tops.current;
    tops.current = now;
    const moved = lastOrder.current !== order;
    lastOrder.current = order;
    if (!moved || !was.size || reduced.current || now.size > MOST_ANIMATED) return;
    for (const [id, el] of rowEls.current) {
      const from = was.get(id);
      if (from === undefined) {
        gsap.fromTo(el, { opacity: 0, y: -6 }, { opacity: 1, y: 0, ...timing("summon"), clearProps: "opacity,transform" });
        continue;
      }
      const dy = from - (now.get(id) ?? from);
      if (dy) gsap.fromTo(el, { y: dy }, { y: 0, ...timing("travel"), overwrite: "auto", clearProps: "transform" });
    }
  });

  const press = (row: Row) => {
    sound?.play("tap");
    onRowPress?.(row);
  };
  const onRowClick = (row: Row) => (event: MouseEvent<HTMLTableRowElement>) => {
    if (!onRowPress || (event.target as Element).closest(INTERACTIVE)) return;
    press(row);
  };

  /* ---------------------------------------------------------------- draw */

  const columnCount = columns.length + (selectable ? 1 : 0) + (rowActions ? 1 : 0);
  const scrollStyle: CSSProperties | undefined = height === undefined ? undefined : { maxHeight: typeof height === "number" ? `${height}px` : height };

  return (
    <div
      ref={scroll}
      className="echo-table__scroll"
      role="region"
      aria-label={caption}
      tabIndex={0}
      style={scrollStyle}
      data-height={height === undefined ? undefined : ""}
    >
      <table
        className={cx("echo-table", className)}
        data-striped={striped ? "" : undefined}
        data-size={size}
        data-sticky={height === undefined ? undefined : ""}
        data-virtual={windowed ? "" : undefined}
        aria-busy={loading || undefined}
        aria-rowcount={windowed ? shown.length + 1 : undefined}
        {...rest}
      >
        <caption className={cx("echo-table__caption", hideCaption && "echo-table__sr")}>{caption}</caption>
        <thead className="echo-table__head">
          <tr className="echo-table__row" aria-rowindex={windowed ? 1 : undefined}>
            {selectable ? (
              <th className="echo-table__header-cell echo-table__select" scope="col">
                <Checkbox
                  aria-label="Select every row shown"
                  checked={allShown}
                  indeterminate={someShown}
                  onCheckedChange={(on) => selectAll(on)}
                />
              </th>
            ) : null}
            {columns.map((column) => {
              const active = sort?.column === column.key ? sort.direction : undefined;
              const align = column.align ?? (column.numeric ? "end" : "start");
              return (
                <th
                  key={column.key}
                  className="echo-table__header-cell"
                  data-align={align}
                  scope="col"
                  aria-sort={active}
                >
                  {column.sortable ? (
                    <button type="button" className="echo-table__sort" onClick={() => setSort(column)} data-active={active}>
                      <span>{column.header}</span>
                      <span className="echo-table__pips" aria-hidden>
                        <i data-lit={active === "ascending" ? "" : undefined} />
                        <i data-lit={active === "descending" ? "" : undefined} />
                      </span>
                    </button>
                  ) : (
                    column.header
                  )}
                </th>
              );
            })}
            {rowActions ? (
              <th className="echo-table__header-cell echo-table__actions" scope="col">
                <span className="echo-table__sr">Actions</span>
              </th>
            ) : null}
          </tr>
        </thead>
        <tbody className="echo-table__body">
          {loading ? (
            Array.from({ length: LOADING_ROWS }, (_, i) => (
              <tr key={`loading-${i}`} className="echo-table__row echo-table__loading" aria-hidden>
                {Array.from({ length: columnCount }, (_, j) => (
                  <td key={j} className="echo-table__cell">
                    <span className="echo-table__skeleton" style={{ "--echo-table-skeleton": `${55 + ((i * 7 + j * 13) % 40)}%` } as CSSProperties} />
                  </td>
                ))}
              </tr>
            ))
          ) : shown.length === 0 ? (
            <tr className="echo-table__row">
              <td className="echo-table__cell echo-table__empty" colSpan={columnCount}>
                {query ? `Nothing matches “${filter.trim()}”.` : (empty ?? "Nothing here yet.")}
              </td>
            </tr>
          ) : (
            <>
              {start > 0 ? (
                <tr className="echo-table__spacer" aria-hidden style={{ height: start * rowHeight }}>
                  <td colSpan={columnCount} />
                </tr>
              ) : null}
              {drawn.map((row, i) => {
                const id = getRowId(row);
                const on = selectedSet.has(id);
                return (
                  <tr
                    key={id}
                    ref={(el) => {
                      if (el) rowEls.current.set(id, el);
                      else rowEls.current.delete(id);
                    }}
                    className="echo-table__row"
                    aria-rowindex={windowed ? start + i + 2 : undefined}
                    data-selected={on ? "" : undefined}
                    data-pressable={onRowPress ? "" : undefined}
                    onClick={onRowPress ? onRowClick(row) : undefined}
                  >
                    {selectable ? (
                      <td className="echo-table__cell echo-table__select">
                        <Checkbox aria-label={`Select ${labelOf(row)}`} checked={on} onCheckedChange={(next) => selectRow(id, next)} />
                      </td>
                    ) : null}
                    {columns.map((column) => {
                      const align = column.align ?? (column.numeric ? "end" : "start");
                      const content = column.cell ? column.cell(row) : text(valueOf(column, row));
                      const pressable = onRowPress && column === labelColumn;
                      const inner = pressable ? (
                        <button type="button" className="echo-table__press" onClick={() => press(row)}>
                          {content}
                        </button>
                      ) : (
                        content
                      );
                      return column.rowHeader ? (
                        <th key={column.key} className="echo-table__header-cell" scope="row" data-align={align}>
                          {inner}
                        </th>
                      ) : (
                        <td key={column.key} className="echo-table__cell" data-align={align} data-numeric={column.numeric ? "" : undefined}>
                          {inner}
                        </td>
                      );
                    })}
                    {rowActions ? <td className="echo-table__cell echo-table__actions">{rowActions(row)}</td> : null}
                  </tr>
                );
              })}
              {end < shown.length ? (
                <tr className="echo-table__spacer" aria-hidden style={{ height: (shown.length - end) * rowHeight }}>
                  <td colSpan={columnCount} />
                </tr>
              ) : null}
            </>
          )}
        </tbody>
      </table>
      <p className="echo-table__sr" role="status" aria-live="polite">
        {said}
      </p>
    </div>
  );
}

export { Table } from "./table";
export type { TableProps, TableSize, HeaderCellProps, CellProps, CellAlign } from "./table";
export type { TableDataProps, TableColumn, TableSort, SortDirection, CellValue } from "./table-data";
